input.sparql:
SELECT ?p ?class ?label WHERE {
  ?p rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter"))
  ?p a ?class .
} LIMIT 40

SELECT ?p ?label WHERE {
  ?p a brick:Zone .
  ?p rdfs:label ?label .
  FILTER(CONTAINS(?label, "bot"))
} LIMIT 40

SELECT ?p ?label ?class WHERE {
  ?p a ?class .
  ?p rdfs:label ?label .
  FILTER(?class = brick:Zone || ?class = brick:Zone_Thermostat || ?class = brick:Temperature_Sensor)
  FILTER(CONTAINS(?label, "Perimeter_bot_ZN_4"))
} LIMIT 40

SELECT ?p ?label WHERE {
  ?p a brick:HVAC_Zone .
  ?p rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter_bot_ZN_4"))
} LIMIT 40

SELECT ?p ?label ?ts WHERE {
  ?s brick:isPointOf ?z ;
     a brick:Zone_Air_Temperature_Sensor ;
     rdfs:label ?label .
  ?z rdfs:label "Perimeter_bot_ZN_4" .
  ?s ref:hasExternalReference ?r .
  ?r ref:hasTimeseriesId ?ts .
} LIMIT 40

SELECT ?s ?label ?ts WHERE {
  ?s rdfs:label ?label .
  FILTER(CONTAINS(?label, "Zone_F2_Z05"))
  ?s ref:hasExternalReference ?r .
  ?r ref:hasTimeseriesId ?ts .
} LIMIT 40

SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
  FILTER(CONTAINS(?label, "F2_Z05") || CONTAINS(?label, "Perimeter_bot_ZN_4"))
} LIMIT 40

SELECT ?r ?prop ?val WHERE {
  ?s a brick:Zone_Air_Temperature_Sensor .
  FILTER(?s = ref:hasTimeseriesId || ?s = brick:hasPart)
} LIMIT 10

